    jsonb_build_object('key','ekpe_community_report_next_due_days', 'label','Whole days from the as-of date to the next due date of REG-2026-042 once its filing is recorded', 'unit','days', 'expected',197, 'tol',0.5),
    jsonb_build_object('key','ekpe_waste_return_period_start_days', 'label','Whole days from the as-of date to the start of the period a filing of REG-2026-043 must fall in', 'unit','days', 'expected',-107, 'tol',0.5),
    jsonb_build_object('key','ekpe_abstraction_next_action_after_filing_days', 'label','Whole days from the as-of date to the next action date of REG-2026-044 once its filing is recorded', 'unit','days', 'expected',66, 'tol',0.5),
    jsonb_build_object('key','ekpe_slug_catcher_procedure_review_days', 'label','Whole days from the as-of date to the review date of OPS-PRO-0031', 'unit','days', 'expected',289, 'tol',0.5),
    jsonb_build_object('key','ekpe_emergency_plan_review_days', 'label','Whole days from the as-of date to the review date of HSE-PLA-0009', 'unit','days', 'expected',-380, 'tol',0.5)
