    jsonb_build_object('key','obeakpu_clause_93_last_examined_days', 'label','Whole days from the as-of date to the last examination of 9.3 that counts towards coverage', 'unit','days', 'expected',-575, 'tol',0.5),
    jsonb_build_object('key','obeakpu_closed_major_finding_age_days', 'label','Age of OSF-2026-002', 'unit','days', 'expected',105, 'tol',0.5),
